mapper.select:
SELECT  ROUND(sum(nvl(summary.t0kyxj,0)),2) AS T0KYXJ, /*T日可用现金*/
ROUND(sum(nvl(summary.t1kyxj,0)),2) AS T1KYXJ, /*T+1日可用现金*/
ROUND(sum(nvl(summary.AMOUNT,0)),2) AS ZHXJ /*账户现金*/
FROM (
/*多组合，再汇总一遍*/
SELECT
aa.t0kyxj, aa.t1kyxj, cc.AMOUNT
FROM(
    select
    a.PORTFOLIO_ID,
    sum(
    CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END
    ) AS t0kyxj, /*T日可用现金*/
    sum(
    CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END
    ) AS t1kyxj /*T+1日可用现金*/
    from PTL_CASH_POSITION_RULE a
    LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_004})
    where to_char(a.cdate,'yyyy-MM-dd') = #{cdate} and b.S_HOLDINGTYPE IN (#{S_004})

        AND a.PORTFOLIO_ID in

            #{item}


    GROUP BY a.PORTFOLIO_ID
) aa
LEFT JOIN (

        SELECT d.PORTFOLIO_ID, sum(d.AMOUNT) AMOUNT
        FROM PTL_CASH_POSITION_RULE d
        where to_char(d.cdate,'yyyy-MM-dd') = #{cdate} AND d.HODING_TYPE =#{C_01}

            and d.ACCT_ID in (
                SELECT ACCT_NO from PTL_CAPACCT_INFO where PORTFOLIO_ID in

                    #{item}

                and ACCT_TYPE = #{acctType}
            )


            AND d.PORTFOLIO_ID in

                #{item}


        GROUP BY d.PORTFOLIO_ID
    ) cc ON aa.PORTFOLIO_ID=cc.PORTFOLIO_ID
) summary

select ETR_ENTRUST.ENTRUST_ID, ETR_ENTRUST.PORTFOLIO_ID, (ETR_ENTRUST.ENTRUST_AMT) - NVL(T5.FINISH_AMT, 0) - NVL(T6.ENT_FINISH_AMT, 0) avaNum from ETR_ENTRUST LEFT JOIN ( SELECT ENTRUST_ID , SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS /*报价完成状况表*/ GROUP BY ENTRUST_ID ) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID , SUM(FINISH_AMT) AS FINISH_AMT , SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS/*委托完成状况表*/ GROUP BY ENTRUST_ID ) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID
and ETR_ENTRUST.ENTRUST_ID in
#{item}

SELECT * FROM ( SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus/*指令状态*/ , (NVL(T5.FINISH_AMT,0)+NVL(T7.ENT_FINISH_AMT,0)) finishAmt/*已完成额度(元)*/ , NVL(ETR_ENTRUST.ENTRUST_AMT, 0)
, NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T5.FINISH_AMT,0) - NVL(T7.ENT_FINISH_AMT,0) avaNum/*剩余指令额度(元)*/
, NVL(ETR_ENTRUST.ENTRUST_AMT, 0)- NVL(ETR_ENTRUST_ADD.FORCED_FINISH_AMT,0) - NVL(T5.FINISH_AMT,0) - NVL(T7.ENT_FINISH_AMT,0) avaNum/*剩余指令额度(元)*/
, ROUND(NVL(C2.totalShareAmt,0)) finishDealAmt/*已成交额度(元)*/ , ROUND(NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(C2.totalShareAmt,0)) avaDealAmt/*剩余成交额度(元)*/ , trunc(nvl(NVL(T5.FINISH_AMT, 0)+ NVL(T7.ENT_FINISH_AMT, 0),0)/(ETR_ENTRUST.ENTRUST_AMT),4)*100 transactioncom/*执行进度(%)*/ , trunc(NVL(C2.totalShareAmt,0)/(ETR_ENTRUST.ENTRUST_AMT),4)*100 tradeFinishPercent/* 成交进度(%)*/ , ETR_ENTRUST.ENTRUST_AMT entrustNum/*指令额度(元)*/ , ETR_ENTRUST.PORTFOLIO_ID portfolioId/*组合代码*/ , PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName/*组合名称*/
,PLEDGE.finprodIds /*质押债券*/ ,PLEDGE.finprodMarketNames /*质押债券*/ ,fp.FINPROD_MARKET_ID bondCode ,fp.FINPROD_ABBR bondAbbrName ,PLEDGES.PLEDGE_NUMBER * 100 pledgePrin
,ETR_ENTRUST_ADD.PLEDGE_STOCK_ID pledgeStockId/*质押券库*/ ,ETR_SEC_STOCK.PLEDGE_STOCK_NAME pledgeStockName/*质押券库*/
, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpreed/*清算速度*/ , ETR_ENTRUST.PS ps/*交易方向*/ , ETR_ENTRUST.PRICE_MODEL priceModel/* 价格模式code*/ , ETR_ENTRUST_ADD.TERM_DAYS repoTerm/*回购期限*/ , ETR_ENTRUST.PRICE*100 tradeYield/*回购利率(%)*/ , ETR_ENTRUST.INV_MANAGER_ID invManagerId/*投资经理ID*/ , SU.real_name invManagerName/*投资经理名称*/ , MCP.COUNTER_ID counterId/* 交易对手*/ , MCP.COUNTER_NAME counterName/* 交易对手名称*/ , MCP.PARTY_ID counterPartyId , ETR_ENTRUST.ENTRUST_DATE ENTRUST_DATE/* 指令日期*/ , to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME, 'hh24:mi:ss') TRANSMIT_TIME/* 指令下达时间*/ , ETR_ENTRUST.ENTRUST_ID entrustId/*指令代码*/ , ETR_ENTRUST.REMARK remark/* 备注*/
, ETR_ENTRUST.VDATE vdate/*委托开始日*/ , ETR_ENTRUST.MDATE mdate/*委托结束日*/ , ETR_ENTRUST_ADD.QUOTE_TYPE quoteType/*报价方式*/ , MCCI.PARTY_ID mySide/* 本方 */ , MCCI.PARTY_ABBR mySideAbbr/* 本方名称 */ , ( SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MCCI.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MCCI.PARTY_ID)) mySideTrader /* 本方交易员 */ , ( SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MCCI.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MCCI.PARTY_ID)) mySideTraderName/* 本方交易员名称 */ , ETR_ENTRUST.COUNTER_TRADER counterTrader/* 对手方交易员*/ , MST_CFETS_CT.TRADER_NAME counterTraderName/* 对手方交易员名称*/ , ETR_ENTRUST.CCY settleCcy/* 币种*/ , ETR_ENTRUST.CCY ccy/* 币种*/ , IPAR.CFETS_ACCT_TYPE secAcctSource/* 银行间账户类型，自营/理财*/ , IPAR.PARTY_ID partyId/* 交易成员ID，21位编号*/ , ETR_ENTRUST_ADD.SEC_ACCT_ID secManageAcctId/* 证券账户代码*/ , SECACCT1.ACCT_NO secManageAcctIdZZ/* 中债登 证券账户代码*/ , SECACCT2.ACCT_NO secManageAcctIdSQ/* 上清所 证券账户代码*/ , ETR_ENTRUST_ADD.TERM_TYPE termType /*期限品种*/ , ETR_ENTRUST.TRADE_MARKET/*交易场所，银行间、上交所、深交所、柜面等*/ FROM ETR_ENTRUST INNER JOIN PTL_PORTFOLIO ON ETR_ENTRUST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN ( select PORTFOLIO_ID,ACCT_NO from PTL_SEC_ACCT psa inner join STL_SEC_ACCT_INFO ssai on psa.ACCT_NO = ssai.SEC_ACCT_ID and ssai.REGIST_ORG in ('01') and NVL(ssai.sec_acct_type, 'SEC') = 'SEC' and TRADE_PLACE = '01' ) SECACCT1 ON ETR_ENTRUST.PORTFOLIO_ID = SECACCT1.PORTFOLIO_ID LEFT JOIN ( select PORTFOLIO_ID,ACCT_NO from PTL_SEC_ACCT psa inner join STL_SEC_ACCT_INFO ssai on psa.ACCT_NO = ssai.SEC_ACCT_ID and ssai.REGIST_ORG in ('02') and NVL(ssai.sec_acct_type, 'SEC') = 'SEC' and TRADE_PLACE = '01' ) SECACCT2 ON ETR_ENTRUST.PORTFOLIO_ID = SECACCT2.PORTFOLIO_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS
INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA IPAR ON ETR_ENTRUST.PORTFOLIO_ID = IPAR.PORTFOLIO_ID AND IPAR.CFETS_ACCT_TYPE = '01' LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON IPAR.PARTY_ID = MCCI.PARTY_ID LEFT JOIN SYS_USER SU ON ETR_ENTRUST.INV_MANAGER_ID = SU.USER_NAME LEFT JOIN MST_CFETS_CUSTOMER_TRADER MST_CFETS_CT ON MST_CFETS_CT.TRADER_ID = ETR_ENTRUST.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = ETR_ENTRUST.COUNTER_ID
LEFT JOIN ( select ENTRUST_ID,
listagg(fp.FINPROD_ID, ',')within group(order by ENTRUST_ID) AS finprodIds, listagg(fp.FINPROD_ABBR, ',')within group(order by ENTRUST_ID) AS finprodMarketNames from ETR_PLEDGE ep left join FIN_PRODUCT fp on ep.FINPROD_ID = fp.FINPROD_ID group by ENTRUST_ID ) PLEDGE /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON PLEDGE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_PLEDGE PLEDGES on PLEDGES.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join FIN_PRODUCT fp on PLEDGES.FINPROD_ID = fp.FINPROD_ID/*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/
LEFT JOIN ETR_SEC_STOCK ON ETR_SEC_STOCK.PLEDGE_STOCK_ID = ETR_ENTRUST_ADD.PLEDGE_STOCK_ID
LEFT JOIN (select sum(SHARE_AMT) totalShareAmt,tpda.ENTRUST_ID from TRD_PRODUCT_DEAL tpd left join TRD_PRODUCT_DEAL_ADD tpda on tpd.TRADE_ID = tpda.TRADE_ID where tpd.IS_CANCEL = 'N' and tpd.TRADE_STATUS = '01' group by tpda.ENTRUST_ID ) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN SYS_DATADICT_LIST D ON ETR_ENTRUST.ENTRUST_STATUS = D.ITEM_CODE and D.DICT_CODE = 'ENTRUST_STATUS'/*指令状态参数字典 模糊查询用*/ LEFT JOIN SYS_DATADICT_LIST E ON ETR_ENTRUST.PS = E.ITEM_CODE and E.DICT_CODE = 'PS'/*交易方向 模糊查询用*/ LEFT JOIN SYS_DATADICT_LIST F ON ETR_ENTRUST.PRICE_MODEL = F.ITEM_CODE and F.DICT_CODE = 'PRICE_MODEL' WHERE ETR_ENTRUST.FINPROD_TYPE2 in (#{finprodType2_F02},#{finprodType2_F03}) AND ETR_ENTRUST.TRADE_MARKET IN (#{tradeMarket01} , #{tradeMarket02}) AND ETR_ENTRUST.PS IN (#{ps_03} , #{ps_04} ) AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple}, #{entrustStatusReturn})
/* 没有 ETR_ENTRUST.ENTRUST_STATUS = '---' or 会出现 [08000][17410] 无法从套接字读取更多的数据 错误 为什么?*/ AND (ETR_ENTRUST.ENTRUST_STATUS = '---' or ETR_ENTRUST.ENTRUST_ID like concat('%',concat(#{entrustIdSearch},'%')))
/* 查询条件 指令状态*/ AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
/* 查询条件 指令日期区间开始日 处于委托日期区间内*/ AND ETR_ENTRUST.ENTRUST_DATE >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
/* 查询条件 指令日期区间结束日 处于委托日期区间内*/ AND ETR_ENTRUST.ENTRUST_DATE <= to_date(#{entrustDateEnd}, 'yyyy-MM-dd')
AND ETR_ENTRUST.PORTFOLIO_ID IN
#{item}
AND ETR_ENTRUST.PS = #{ps}
/* 查询条件 交易方向*/ AND ETR_ENTRUST.ps IN
#{item}
AND ETR_ENTRUST.PRICE_MODEL = #{priceModel}
/* 查询条件 价格模式*/ AND ETR_ENTRUST.PRICE_MODEL IN
#{item}
AND ETR_ENTRUST.ENTRUST_ID = #{entrustId}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpeed}
/* 查询条件 清算速度*/ AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') IN
#{item}
/* 查询条件 投资经理*/ AND ETR_ENTRUST.INV_MANAGER_ID IN
#{item}
AND IPAR.PARTY_ID = #{mySide}
/* 查询条件 交易员*/ AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
/* 查询条件 开户来源，理财、自营*/ AND STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE = #{secAcctSource}
/* 查询条件 回购期限*/ AND ETR_ENTRUST_ADD.TERM_DAYS = #{repoTerm}
/* 查询条件 交易对手*/ AND ( MCP.PARTY_ID = #{partyId} OR ETR_ENTRUST.COUNTER_ID IS NULL OR MCP.COUNTER_ID = #{partyId} )
/* 查询条件 回购利率*/ AND ETR_ENTRUST.PRICE = #{tradeYield}
/* 查询条件 证券账户*/ AND ETR_ENTRUST_ADD.SEC_ACCT_ID = #{secAcctId}
/* 查询条件 质押券库*/ AND ETR_ENTRUST.PLEDGE_STOCK_ID IN
#{item}
AND ( ETR_ENTRUST.ENTRUST_STATUS like '%' || #{search} || '%' /*指令状态*/ OR D.ITEM_VALUE LIKE '%' || #{search} || '%' /*指令状态*/ OR to_char(trunc(nvl(NVL(T5.FINISH_AMT, 0)+NVL(T7.ENT_FINISH_AMT, 0),0)/(ETR_ENTRUST.ENTRUST_AMT),4)*100) = #{search} /*执行进度(%)*/ OR to_char(trunc(NVL(C2.totalShareAmt, 0)/(ETR_ENTRUST.ENTRUST_AMT),4)*100) = #{search}/* 成交进度(%)*/ OR to_char(ETR_ENTRUST.ENTRUST_AMT,'FM9999999999999990.90') = #{search} /*指令额度(元)*/ OR ETR_ENTRUST.PORTFOLIO_ID LIKE '%' || #{search} || '%' /*组合代码*/ OR PTL_PORTFOLIO.PORTFOLIO_NAME LIKE '%' || #{search} || '%' /*组合名称*/ OR ETR_ENTRUST_ADD.SETTLE_SPREED LIKE '%' || decode(#{search},'T+0','0','T+1','1','T+2','2',#{search}) ||'%' /*清算速度*/ OR ETR_ENTRUST.PS LIKE '%' || #{search} || '%' /*交易方向*/ OR E.ITEM_VALUE LIKE '%' || #{search} || '%' /*交易方向*/ OR ETR_ENTRUST.PRICE_MODEL LIKE '%' || #{search} || '%' /*价格模式*/ OR F.ITEM_VALUE LIKE '%' || #{search} || '%' /*价格模式*/ OR to_char(ETR_ENTRUST_ADD.TERM_DAYS) = #{search} /*回购期限*/ OR to_char(ETR_ENTRUST.PRICE,'FM99990.9990') = #{search} /*回购利率*/ OR ETR_ENTRUST.INV_MANAGER_ID LIKE '%' || #{search} || '%' /*投资经理*/ OR SU.real_name LIKE '%' || #{search} || '%' /*投资经理*/ OR MCP.COUNTER_ID LIKE '%' || #{search} || '%' /*交易对手*/ OR MCP.COUNTER_NAME LIKE '%' || #{search} || '%' /*交易对手*/ OR to_char(ETR_ENTRUST.ENTRUST_DATE,'yyyy-MM-dd') = #{search} /*指令日期*/ OR to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME, 'hh24:mi:ss') = #{search} /*下达时间*/ OR ETR_ENTRUST.ENTRUST_ID LIKE '%' || #{search} || '%' /*指令代码*/ OR ETR_ENTRUST.REMARK LIKE '%' || #{search} || '%' /*备注*/
OR PLEDGE.finprodIds LIKE '%' || #{search} || '%'/*质押债券*/ OR PLEDGE.finprodMarketNames LIKE '%' || #{search} || '%'/*质押债券*/
OR ETR_ENTRUST_ADD.PLEDGE_STOCK_ID LIKE '%' || #{search} || '%' /*质押券库*/ OR ETR_SEC_STOCK.PLEDGE_STOCK_NAME LIKE '%' || #{search} || '%' /*质押券库*/
)
and ETR_ENTRUST.ENTRUST_ID in
#{item}
and ETR_ENTRUST.ENTRUST_ID not in
#{item}
and ( ETR_ENTRUST.COUNTER_ID in ( select COUNTER_ID from ETR_ENTRUST where ENTRUST_ID in
#{item}
) or ETR_ENTRUST.COUNTER_ID is null )
order by decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7),ETR_ENTRUST_ADD.TRANSMIT_TIME,ETR_ENTRUST.ps)
order by ${sort} ${direction}

SELECT fp.FINPROD_MARKET_ID bondCode ,fp.FINPROD_ABBR bondAbbrName ,fp.FINPROD_ID finprodId ,pp.PORTFOLIO_ID portfolioId ,pp.PORTFOLIO_NAME portfolioName ,fp.MDATE mdate ,NVL(TABLE01.pledStrdPrinAmt,0) avaPledgePrin ,NVL(pledgeList.PLEDGE_NUMBER,0)*100 pledgePrin ,NVL(pledgeList.PLEDGE_NUMBER,0)*100 pledgePrinInit ,mbvi.NETPRICE firstNetPrice ,pledgeList.PLEDGE_RATIO*100 pledgeRatio ,nvl(TABLE01.pledgeAmount,0) prin ,eea.PLEDGE_STOCK_ID pledgeStockId ,ess.PLEDGE_STOCK_NAME pledgeStockName ,MBCR.GRADE_RESULT gradeResult /*债项评级*/ , fp.REGIST_ORG repRegistOrg
,pledgeList.bussId entrustId
FROM ( SELECT ENTRUST_ID bussId ,FINPROD_ID pledgeId ,PLEDGE_FACE_VALUE ,PLEDGE_NUMBER ,PLEDGE_RATIO ,PLEDGE_NUMBER*100 FROM ETR_PLEDGE WHERE
ENTRUST_ID IN
#{item}
UNION ALL SELECT ENTRUST_ID bussId ,FINPROD_ID pledgeId ,PLEDGE_FACE_VALUE ,PLEDGE_NUMBER ,PLEDGE_RATIO ,PLEDGE_NUMBER*100 FROM WFL_ETR_PLEDGE WHERE
ENTRUST_ID IN
#{item}
) pledgeList LEFT JOIN ETR_ENTRUST ee ON ee.ENTRUST_ID = pledgeList.bussId left join ( SELECT V.SEC_ACCT_ID AS SECACCTID, PSA.PORTFOLIO_ID, R.FINPROD_ID FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V LEFT JOIN FIN_PRODUCT R ON R.REGIST_ORG = V.REGIST_ORG and V.TRADE_PLACE = R.trade_market WHERE PSA.ACCT_NO = V.SEC_ACCT_ID AND V.SEC_ACCT_TYPE = 'SEC') secAcct on secAcct.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.FINPROD_ID = pledgeList.pledgeId INNER JOIN PTL_PORTFOLIO pp ON ee.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD eea ON eea.ENTRUST_ID = pledgeList.bussId LEFT JOIN ETR_SEC_STOCK ess ON ess.PLEDGE_STOCK_ID=eea.PLEDGE_STOCK_ID LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID /*组合代码*/ ,TEMP.PORTFOLIO_NAME ,TEMP.SEC_ACCT_ID /*证券账户/通道代码*/ ,TEMP.FINPROD_ID /*分支序号*/ ,SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt /*可质押券面总额*/ ,SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID ,pp.PORTFOLIO_NAME ,espr.SEC_ACCT_ID ,espr.FINPROD_ID ,CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt /*可质押券面总额*/ ,CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM PTL_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{platDate}, 'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID ,TEMP.PORTFOLIO_NAME ,TEMP.SEC_ACCT_ID ,TEMP.FINPROD_ID HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON TABLE01.FINPROD_ID = pledgeList.pledgeId AND TABLE01.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.SECACCTID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM ,O_CODE ,GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = fp.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON fp.FINPROD_MARKET_ID = mbvi.SEC_ID
and fp.FINPROD_ID =#{finprodId, jdbcType=VARCHAR}
and FPT.TYPE_11 =#{finprodType, jdbcType=VARCHAR}
and fp.REGIST_ORG =#{repRegistOrg, jdbcType=VARCHAR}

SELECT fp.FINPROD_MARKET_ID bondCode ,fp.FINPROD_ABBR bondAbbrName ,fp.FINPROD_ID finprodId ,pp.PORTFOLIO_ID portfolioId ,pp.PORTFOLIO_NAME portfolioName ,fp.MDATE mdate ,NVL(TABLE01.pledStrdPrinAmt,0) avaPledgePrin ,sum(NVL(pledgeList.PLEDGE_NUMBER, 0)*100) pledgePrin ,sum(NVL(pledgeList.PLEDGE_NUMBER, 0)*100) pledgePrinInit ,mbvi.NETPRICE firstNetPrice ,pledgeList.PLEDGE_RATIO*100 pledgeRatio ,nvl(TABLE01.pledgeAmount,0) prin ,eea.PLEDGE_STOCK_ID pledgeStockId ,ess.PLEDGE_STOCK_NAME pledgeStockName ,MBCR.GRADE_RESULT gradeResult /*债项评级*/ , fp.REGIST_ORG repRegistOrg FROM ( select ENTRUST_ID bussId, FINPROD_ID pledgeId,PLEDGE_RATIO, sum(PLEDGE_NUMBER) PLEDGE_NUMBER from ( select ep.ENTRUST_ID ,ep.FINPROD_ID ,(nvl(ep.PLEDGE_NUMBER,0) - nvl(wrfp.PLEDGE_NUMBER,0) - nvl(rfp.PLEDGE_NUMBER,0)) PLEDGE_NUMBER ,ep.PLEDGE_RATIO from ETR_PLEDGE ep left join WFL_REG_FIN_PLEDGE wrfp on wrfp.PLEDGE_FINPROD_ID = ep.FINPROD_ID and ep.ENTRUST_ID = wrfp.ENTRUST_ID left join ( select t.ENTRUST_ID, t.PLEDGE_FINPROD_ID, t.PLEDGE_NUMBER from REG_FIN_PLEDGE t left join REG_FIN_PRODUCT_DEAL rfpd on t.TRADE_ID = rfpd.TRADE_ID where rfpd.IS_CANCEL = 'N' and rfpd.TRADE_STATUS ='01' ) rfp on rfp.PLEDGE_FINPROD_ID = ep.FINPROD_ID and ep.ENTRUST_ID = rfp.ENTRUST_ID
ep.ENTRUST_ID in
#{item}
) group by ENTRUST_ID , FINPROD_ID ,PLEDGE_RATIO ) pledgeList LEFT JOIN ETR_ENTRUST ee ON ee.ENTRUST_ID = pledgeList.bussId left join ( SELECT V.SEC_ACCT_ID AS SECACCTID, PSA.PORTFOLIO_ID, R.FINPROD_ID FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V LEFT JOIN FIN_PRODUCT R ON R.REGIST_ORG = V.REGIST_ORG and V.TRADE_PLACE = R.trade_market WHERE PSA.ACCT_NO = V.SEC_ACCT_ID AND V.SEC_ACCT_TYPE = 'SEC') secAcct on secAcct.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.FINPROD_ID = pledgeList.pledgeId INNER JOIN PTL_PORTFOLIO pp ON ee.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN ETR_ENTRUST_ADD eea ON eea.ENTRUST_ID = pledgeList.bussId LEFT JOIN ETR_SEC_STOCK ess ON ess.PLEDGE_STOCK_ID=eea.PLEDGE_STOCK_ID LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID /*组合代码*/ ,TEMP.PORTFOLIO_NAME ,TEMP.SEC_ACCT_ID /*证券账户/通道代码*/ ,TEMP.FINPROD_ID /*分支序号*/ ,SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt /*可质押券面总额*/ ,SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID ,pp.PORTFOLIO_NAME ,espr.SEC_ACCT_ID ,espr.FINPROD_ID ,CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt /*可质押券面总额*/ ,CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM PTL_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID LEFT JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{platDate}, 'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID ,TEMP.PORTFOLIO_NAME ,TEMP.SEC_ACCT_ID ,TEMP.FINPROD_ID HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON TABLE01.FINPROD_ID = pledgeList.pledgeId AND TABLE01.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.SECACCTID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = fp.FINPROD_ID LEFT JOIN ( SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM ,O_CODE ,GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = fp.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON fp.FINPROD_MARKET_ID = mbvi.SEC_ID
and fp.FINPROD_ID =#{finprodId, jdbcType=VARCHAR}
and FPT.TYPE_11 =#{finprodType, jdbcType=VARCHAR}
and fp.REGIST_ORG =#{repRegistOrg, jdbcType=VARCHAR}
group by fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, fp.FINPROD_ID, pp.PORTFOLIO_ID, pp.PORTFOLIO_NAME, fp.MDATE, TABLE01.pledStrdPrinAmt, mbvi.NETPRICE, pledgeList.PLEDGE_RATIO, TABLE01.pledgeAmount, eea.PLEDGE_STOCK_ID, ess.PLEDGE_STOCK_NAME, MBCR.GRADE_RESULT, fp.REGIST_ORG

select * from ( SELECT DISTINCT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ PP.PORTFOLIO_NAME portfolioName,/*组合名称*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ FIN_PRODUCT.FINPROD_MARKET_ID bondCode,/*市场代码*/ FIN_PRODUCT.FINPROD_ABBR bondAbbrName,/*金融产品简称*/ NVL(TABLE01.pledgeAmount,0) prin,/*券面总额*/ NVL(TABLE01.pledStrdPrinAmt,0) avaPledgePrin,/*可质押券面总额*/ NVL(TABLE01.pledgePrin,0) pledgePrin,/*质押券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ sdl.ITEM_VALUE gradeResult,/*债项评级*/ mbvi.NETPRICE firstNetPrice,/*首次净价*/ FIN_PRODUCT.REGIST_ORG repRegistOrg,/*登记托管机构*/ case when EEP.SCALE is not null then round(nvl(EEP.SCALE,100)/100,4)*100 when mbvi.NETPRICE>nvl(prinAmt.prinAmt,100) then round(100/100,4)*100 when mbvi.NETPRICE is null then round(nvl(prinAmt.prinAmt,100)/100,4)*100 else round(mbvi.NETPRICE/nvl(prinAmt.prinAmt,100),4)*100 end as pledgeRatio, /*折算比例*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*市场代码*/ EEP.PLEDGE_STOCK_ID pledgeStockId/*债券库代码*/, ESS.PLEDGE_STOCK_NAME pledgeStockName/*债券库名称*/, CASE WHEN FIN_PRODUCT2.IS_CHL = 'Y' THEN FIN_PRODUCT2.FINPROD_NAME ELSE STL_SEC_ACCT_INFO.SEC_ACCT_NAME END AS secAcctStr ,NVL(PP.PARENT_PORTFOLIO_ID, PP.PORTFOLIO_ID) parentPortfolioId FROM ( SELECT TEMP.PORTFOLIO_ID, /*组合代码*/ TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, /*证券账户/通道代码*/ TEMP.FINPROD_ID, /*分支序号*/ SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt, /*可质押券面总额*/ SUM(TEMP.pledgeAmount) pledgeAmount, /*已质押质押券面总额*/ SUM(TEMP.pledgePrin) pledgePrin /*质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID, pp.PORTFOLIO_NAME, espr.SEC_ACCT_ID, espr.FINPROD_ID, CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt, /*可质押券面总额*/ CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount, /*已质押质押券面总额*/ CASE WHEN espr.HODING_TYPE=#{A_001} THEN espr.AMOUNT ELSE 0 END pledgePrin FROM PTL_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID left JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{platDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012} or espr.HODING_TYPE=#{A_001}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ LEFT JOIN STL_SEC_ACCT_INFO on TABLE01.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 on TABLE01.SEC_ACCT_ID = FIN_PRODUCT2.FINPROD_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = TABLE01.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO/*以上获取债券小于等于平台日的最新估值行情*/ ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID left join ( select 100-sum(nvl(PRIN_AMT,0)) prinAmt,FINPROD_ID from FIN_CASH_PLAN WHERE MDATE <= to_date(#{platDate},'yyyy-mm-dd') group by FINPROD_ID) prinAmt on prinAmt.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{platDate},'yyyy-MM-dd') and GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = FIN_PRODUCT.FINPROD_MARKET_ID AND MBCR.NUM = 1 left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE = 'SVR_MAIN_GRADE' and sdl.ITEM_CODE = MBCR.GRADE_RESULT LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON FIN_PRODUCT.FINPROD_MARKET_ID = mbvi.SEC_ID LEFT JOIN ETR_ENTRUST_PLEDGE EEP ON TABLE01.PORTFOLIO_ID = EEP.PORTFOLIO_ID AND TABLE01.SEC_ACCT_ID = EEP.SEC_ACCT_ID AND TABLE01.FINPROD_ID = EEP.FINPROD_ID LEFT JOIN ptl_portfolio PP ON TABLE01.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN ETR_SEC_STOCK ESS ON ESS.PLEDGE_STOCK_ID = EEP.PLEDGE_STOCK_ID WHERE 1=1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET = #{TRADEPLACE01}
AND TABLE01.PORTFOLIO_ID in ( select PORTFOLIO_ID from ETR_ENTRUST where ENTRUST_ID in
#{item}
)
AND EEP.PLEDGE_STOCK_ID in ( select PLEDGE_STOCK_ID from ETR_ENTRUST_ADD where ENTRUST_ID in
#{item}
)
AND EEP.PLEDGE_STOCK_ID in
#{item}
AND fp.FINPROD_ID in
#{item}
AND FPT.TYPE_11 in
#{item}
AND FIN_PRODUCT.REGIST_ORG in
#{item}
)
AND portfolioId||finprodId not in
#{item}

