fp.VDATE <=TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND fp.MDATE >=TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND fp.TRADE_MARKET = '01'/*银行间*/
AND fp.FINPROD_ID in
