SELECT bondCode, bondAbbrName, finprodId, portfolioId, portfolioName, mdate, SUM(avaPledgePrin) avaPledgePrin, SUM(pledgePrin) pledgePrin, firstNetPrice, SUM(prin) prin, gradeResult, pledgeRatio, repRegistOrg FROM ( SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.FINPROD_ID finprodId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, fp.MDATE mdate, (NVL(TABLE01.pledStrdPrinAmt, 0)) avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, nvl(TABLE01.pledgeAmount,0) prin, sdl.ITEM_VALUE gradeResult,/*债项评级*/ fp.REGIST_ORG repRegistOrg FROM ( SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_NUMBER*100 FROM ETR_PLEDGE WHERE
ENTRUST_ID in
#{item}
union all SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_NUMBER*100 FROM WFL_ETR_PLEDGE WHERE
ENTRUST_ID in
#{item}
) pledgeList left join ETR_ENTRUST ee on ee.ENTRUST_ID = pledgeList.bussId left join ( SELECT V.SEC_ACCT_ID AS SECACCTID, PSA.PORTFOLIO_ID, R.FINPROD_ID FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V LEFT JOIN FIN_PRODUCT R ON R.REGIST_ORG = V.REGIST_ORG and V.TRADE_PLACE = R.trade_market WHERE PSA.ACCT_NO = V.SEC_ACCT_ID AND V.SEC_ACCT_TYPE = 'SEC') secAcct on secAcct.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.FINPROD_ID = pledgeList.pledgeId INNER JOIN PTL_PORTFOLIO pp ON ee.PORTFOLIO_ID = pp.PORTFOLIO_ID left join ETR_ENTRUST_ADD eea on eea.ENTRUST_ID = pledgeList.bussId LEFT JOIN( SELECT TEMP.PORTFOLIO_ID, /*组合代码*/ TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, /*证券账户/通道代码*/ TEMP.FINPROD_ID, /*分支序号*/ SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt, /*可质押券面总额*/ SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID, pp.PORTFOLIO_NAME, espr.SEC_ACCT_ID, espr.FINPROD_ID, CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt, /*可质押券面总额*/ CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM PTL_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID left JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{platDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012}) ) TEMP GROUP BY TEMP.PORTFOLIO_ID, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON TABLE01.FINPROD_ID = pledgeList.pledgeId AND TABLE01.PORTFOLIO_ID = ee.PORTFOLIO_ID and secAcct.SECACCTID = TABLE01.SEC_ACCT_ID LEFT JOIN ( SELECT PORTFOLIO_ID,FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE CDATE = TO_DATE(#{platDate, jdbcType=VARCHAR}, 'yyyy-MM-dd') AND HODING_TYPE = #{POSITION_TYPE_04} GROUP BY PORTFOLIO_ID,FINPROD_ID ) pledge ON pledge.PORTFOLIO_ID = ee.PORTFOLIO_ID AND pledge.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = fp.FINPROD_ID LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{platDate, jdbcType=VARCHAR},'yyyy-MM-dd') and GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = fp.FINPROD_MARKET_ID AND MBCR.NUM = 1 left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE = 'SVR_MAIN_GRADE' and sdl.ITEM_CODE = MBCR.GRADE_RESULT LEFT JOIN ( SELECT T2.SEC_ID, T2.PRICE, T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{platDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = ( CASE WHEN tmp2.trade_market IN (#{TRADEPLACE03},#{TRADEPLACE04}) THEN 'CSD' ELSE 'CBC' END) GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) mbvi/*以上获取债券小于等于平台日的最新估值行情*/ ON fp.FINPROD_MARKET_ID = mbvi.SEC_ID
AND fp.FINPROD_ID in
#{item}
AND FPT.TYPE_11 in
#{item}
AND fp.REGIST_ORG in
#{item}
)
AND portfolioId||finprodId not in
#{item}
group by bondCode, bondAbbrName, finprodId, portfolioId, portfolioName, mdate, firstNetPrice, gradeResult, pledgeRatio, repRegistOrg

select ENTRUST_ID entrustId, FINPROD_ID finprodId, sum(PLEDGE_NUMBER) avaPledgePrin from ( select ENTRUST_ID, FINPROD_ID, PLEDGE_NUMBER from ETR_PLEDGE ep
ep.ENTRUST_ID in
#{item}
union all select ENTRUST_ID, PLEDGE_FINPROD_ID FINPROD_ID, -1*PLEDGE_NUMBER from WFL_REG_FIN_PLEDGE wrfp
wrfp.ENTRUST_ID in
#{item}
AND wrfp.WORKFLOW_ID != #{workflowId}
union all select rfp.ENTRUST_ID, rfp.PLEDGE_FINPROD_ID FINPROD_ID, -1*rfp.PLEDGE_NUMBER from REG_FIN_PLEDGE rfp left join REG_FIN_PRODUCT_DEAL rfpd on rfp.TRADE_ID = rfpd.TRADE_ID
rfpd.IS_CANCEL = 'N' and rfpd.TRADE_STATUS = '01'
and rfp.ENTRUST_ID in
#{item}
union all select iqecp.ENTRUST_ID, iqecp.PLEDGE_FINPROD_ID FINPROD_ID, -1*iqecp.PLEDGE_NUMBER from IBU_QUOTE_ENT_CREP_PLEDGE iqecp left join IBU_QUOTE_CREP iqc on iqc.QUOTE_ID = iqecp.QUOTE_ID where iqc.SEND_STATUS = '01'
and iqecp.ENTRUST_ID in
#{item}
union all select wiqecp.ENTRUST_ID, wiqecp.PLEDGE_FINPROD_ID FINPROD_ID, -1*wiqecp.PLEDGE_NUMBER from wfl_IBU_QUOTE_ENT_CREP_PLEDGE wiqecp left join WFL_IBU_QUOTE_CREP wiqc on wiqc.QUOTE_ID = wiqecp.QUOTE_ID
wiqecp.ENTRUST_ID in
#{item}
AND wiqc.WORKFLOW_ID != #{workflowId}
) group by ENTRUST_ID, FINPROD_ID

select sum(T.ENTRUST_AMT) avaNum ,IPAR.PARTY_ID,T.REPO_TERM,T.SETTLE_SPREED from ( select nvl(ee.ENTRUST_AMT - nvl(eea.FORCED_FINISH_AMT, 0) - nvl(rfpd.ENTRUST_AMT, 0) - nvl(wrfpd.TRADE_AMT, 0) - nvl(IBQER.ENTRUST_AMT, 0) - nvl(wiqer.FPRICE_AMT, 0),0) ENTRUST_AMT, ee.PORTFOLIO_ID, eea.TERM_DAYS REPO_TERM, eea.SETTLE_SPREED SETTLE_SPREED from ETR_ENTRUST ee left join ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID left join (select t.TRADE_AMT ENTRUST_AMT, t.ENTRUST_ID from REG_FIN_PRODUCT_DEAL t left join reg_FIN_PRODUCT_DEAL_TOTAL rfpdt on rfpdt.TOTLE_TRADE_ID = t.TOTLE_TRADE_ID where rfpdt.IS_CANCEL = 'N' and rfpdt.TRADE_STATUS = '01' ) rfpd on rfpd.ENTRUST_ID = ee.ENTRUST_ID left join WFL_REG_FIN_PRODUCT_DEAL wrfpd on wrfpd.ENTRUST_ID = ee.ENTRUST_ID
and wrfpd.TOTLE_TRADE_ID != #{totleTradeId}
left join ( select t.FPRICE_AMT ENTRUST_AMT, t.ENTRUST_ID from IBU_QUOTE_ETR_RE t left join IBU_QUOTE_CREP IQC on t.QUOTE_ID = IQC.QUOTE_ID where IQC.SEND_STATUS = '01' ) IBQER on IBQER.ENTRUST_ID = ee.ENTRUST_ID left join WFL_IBU_QUOTE_ETR_RE wiqer on wiqer.ENTRUST_ID = ee.ENTRUST_ID
and wiqer.QUOTE_ID != #{totleTradeId}
where ee.ENTRUST_ID = #{etrId} ) T LEFT JOIN IBU_PORTFOLIO_ACCT_RELA IPAR ON T.PORTFOLIO_ID = IPAR.PORTFOLIO_ID AND IPAR.CFETS_ACCT_TYPE = '01' group by IPAR.PARTY_ID,T.REPO_TERM,T.SETTLE_SPREED

mapper.sql:
select '01' statusValid/*有效*/, '04' quoteType/*交易类型*/, RFPDT.TRADE_DATE tradeDate/*成交日期*/, RFPDT.ps ps/*本方方向*/, null tradeStatus/*报价状态*/, null sendStatus/*发送状态*/, RFPDT.TRADE_AMT tradeAmt/*交易金额*/, RFPDT.RATE rate/*回购利率*/, RFPDT.REPO_TERM repoTerm/*回购期限*/, null quoteRoleType/*本方角色*/, MCCI.PARTY_ABBR ouPartyName/*本方*/, SU.REAL_NAME ouTraderName /*本方交易员*/, case WHEN RFPDT.QUOTE_TYPE = '05' THEN SDL.ITEM_VALUE else MCP.COUNTER_NAME end cpPartyName/*对手方*/, CASE WHEN MCCT.TRADER_NAME is not null THEN MCCT.TRADER_NAME ELSE RFPDT.COUNTER_TRADER END cpTraderName/*对手方交易员*/, DECODE(RFPDT.SETTLE_SPEED, 0, '01', 1, '02') settleSpeed/*清算速度*/, RFPDT.V_SETTLE_DATE vSettleDate/*首次结算日*/, RFPDT.M_SETTLE_DATE mSettleDate/*到期结算日*/, RFPDT.TOTLE_TRADE_ID quoteId/*业务编号*/, TMI.TRD_ID trdId/*成交编号*/, RFPDT.remark remark/*备注*/, RFPDT.CREATE_USER,RFPDT.UPDATE_USER from REG_FIN_PRODUCT_DEAL_TOTAL RFPDT LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = RFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TFPDT.TOTLE_TRADE_ID = TMI.TRD_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON MCCI.PARTY_ID = RFPDT.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = RFPDT.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = RFPDT.COUNTER_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = RFPDT.OU_TRADER_ID LEFT JOIN SYS_DATADICT_LIST SDL ON RFPDT.COUNTER_ID = SDL.ITEM_CODE AND SDL.DICT_CODE = 'REGIST_ORG' where RFPDT.IS_CANCEL = 'N' and RFPDT.TRADE_STATUS != '03' and RFPDT.FINPROD_TYPE2 in ('F02', 'F03') and EXISTS ( SELECT 1 FROM REG_FIN_PRODUCT_DEAL T WHERE T.TOTLE_TRADE_ID = RFPDT.TOTLE_TRADE_ID
AND T.ENTRUST_ID= #{entrustId}
)

select '03' statusValid/*有效*/, '04' quoteType/*交易类型*/, RFPDT.TRADE_DATE tradeDate/*成交日期*/, RFPDT.ps ps/*本方方向*/, null tradeStatus/*报价状态*/, null sendStatus/*发送状态*/, RFPDT.TRADE_AMT tradeAmt/*交易金额*/, RFPDT.RATE rate/*回购利率*/, RFPDT.REPO_TERM repoTerm/*回购期限*/, null quoteRoleType/*本方角色*/, MCCI.PARTY_ABBR ouPartyName/*本方*/, SU.REAL_NAME ouTraderName /*本方交易员*/, case WHEN RFPDT.QUOTE_TYPE = '05' THEN SDL.ITEM_VALUE else MCP.COUNTER_NAME end cpPartyName/*对手方*/, CASE WHEN MCCT.TRADER_NAME is not null THEN MCCT.TRADER_NAME ELSE RFPDT.COUNTER_TRADER END cpTraderName/*对手方交易员*/, DECODE(RFPDT.SETTLE_SPEED, 0, '01', 1, '02') settleSpeed/*清算速度*/, RFPDT.V_SETTLE_DATE vSettleDate/*首次结算日*/, RFPDT.M_SETTLE_DATE mSettleDate/*到期结算日*/, RFPDT.TOTLE_TRADE_ID quoteId/*业务编号*/, TMI.TRD_ID trdId/*成交编号*/, RFPDT.remark remark/*备注*/, RFPDT.CREATE_USER,RFPDT.UPDATE_USER from REG_FIN_PRODUCT_DEAL_TOTAL RFPDT LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = RFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TFPDT.TOTLE_TRADE_ID = TMI.TRD_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON MCCI.PARTY_ID = RFPDT.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = RFPDT.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = RFPDT.COUNTER_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = RFPDT.OU_TRADER_ID LEFT JOIN SYS_DATADICT_LIST SDL ON RFPDT.COUNTER_ID = SDL.ITEM_CODE AND SDL.DICT_CODE = 'REGIST_ORG' where RFPDT.IS_CANCEL = 'Y' and RFPDT.FINPROD_TYPE2 in ('F02', 'F03') AND EXISTS ( SELECT 1 FROM REG_FIN_PRODUCT_DEAL T WHERE T.TOTLE_TRADE_ID = RFPDT.TOTLE_TRADE_ID
AND T.ENTRUST_ID= #{entrustId}
)

select '04' statusValid/*有效*/, '04' quoteType/*交易类型*/, WRFPDT.TRADE_DATE tradeDate/*成交日期*/, WRFPDT.ps ps/*本方方向*/, null tradeStatus/*报价状态*/, null sendStatus/*发送状态*/, WRFPDT.TRADE_AMT tradeAmt/*交易金额*/, WRFPDT.RATE rate/*回购利率*/, WRFPDT.REPO_TERM repoTerm/*回购期限*/, null quoteRoleType/*本方角色*/, MCCI.PARTY_ABBR ouPartyName/*本方*/, SU.REAL_NAME ouTraderName /*本方交易员*/, case WHEN WRFPDT.QUOTE_TYPE = '05' THEN SDL.ITEM_VALUE else MCP.COUNTER_NAME end cpPartyName/*对手方*/, CASE WHEN MCCT.TRADER_NAME is not null THEN MCCT.TRADER_NAME ELSE WRFPDT.COUNTER_TRADER END cpTraderName/*对手方交易员*/, DECODE(WRFPDT.SETTLE_SPEED, 0, '01', 1, '02') settleSpeed/*清算速度*/, WRFPDT.V_SETTLE_DATE vSettleDate/*首次结算日*/, WRFPDT.M_SETTLE_DATE mSettleDate/*到期结算日*/, WRFPDT.TOTLE_TRADE_ID quoteId/*业务编号*/, NULL trdId/*成交编号*/, WRFPDT.remark remark/*备注*/, WRFPDT.CREATE_USER,WRFPDT.UPDATE_USER from WFL_REG_FIN_PRODUCT_DEAL_TOTAL WRFPDT LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON MCCI.PARTY_ID = WRFPDT.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = WRFPDT.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = WRFPDT.COUNTER_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = WRFPDT.OU_TRADER_ID LEFT JOIN SYS_DATADICT_LIST SDL ON WRFPDT.COUNTER_ID = SDL.ITEM_CODE AND SDL.DICT_CODE = 'REGIST_ORG' where WRFPDT.IS_CANCEL = 'N' and WRFPDT.TRADE_STATUS != '03' and WRFPDT.FINPROD_TYPE2 in ('F02', 'F03') AND EXISTS ( SELECT 1 FROM WFL_REG_FIN_PRODUCT_DEAL T WHERE T.TOTLE_TRADE_ID = WRFPDT.TOTLE_TRADE_ID
AND T.ENTRUST_ID= #{entrustId}
)

SELECT CASE WHEN RFPDT.IS_CANCEL = 'Y' THEN '03' ELSE '01' END validStatus, RFPDT.QUOTE_TYPE quoteType, RFPDT.TRADE_AMT tradeAmt, RFPDT.RATE rate, RFPDT.REPO_TYPE repoType, RFPDT.REPO_TERM repoTerm, MCCI2.PARTY_ABBR ouPartyName, case when RFPDT.QUOTE_TYPE = '05' then SDL.ITEM_VALUE else MSCP.COUNTER_NAME end cpPartyName, MSCP.PARTY_ID partyId, NVL(SU.REAL_NAME,SUA.IBU_TRADER) ouTraderName, case when MCCT.TRADER_NAME is not null then MCCT.TRADER_NAME else RFPDT.COUNTER_TRADER end cpTraderName, RFPDT.SETTLE_SPEED settleSpeed/*清算速度*/, RFPDT.V_SETTLE_DATE vSettleDate, RFPDT.M_SETTLE_DATE mSettleDate, RFPDT.TRADE_DATE tradeDate, TFPDT.TRADE_DATE dealDate, EEOH.STATISTICAL_TIMES statisticalTimes, RFPDT.TOTLE_TRADE_ID quoteId, TMI.TRD_ID trdId, RFPDT.PS ps, RFPDT.CLEAR_TYPE settleType, RFPDT.DELIVERY_TYPE deliverytype, RFPDT.M_DELIVERY_TYPE mDeliveryType, RFPDT.CCY ccy, RFPDT.SETT_CCY settCcy, RFPDT.CREATE_USER createUser FROM REG_FIN_PRODUCT_DEAL_TOTAL RFPDT LEFT JOIN MST_COUNTER_PARTY MSCP ON MSCP.COUNTER_ID = RFPDT.COUNTER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI2 ON MCCI2.PARTY_ID = RFPDT.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = RFPDT.COUNTER_TRADER LEFT JOIN SYS_USER SU ON SU.USER_NAME = RFPDT.OU_TRADER_ID LEFT JOIN SYS_USER_ADD SUA ON SU.USER_ID = SUA.USER_ID LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'REGIST_ORG')SDL ON RFPDT.COUNTER_ID = SDL.ITEM_CODE LEFT JOIN (SELECT ENTRUST_ID, COUNT(1) STATISTICAL_TIMES FROM ETR_ENTRUST_OPER_HIS WHERE OPER_TYPE = #{OPR_TYPE_09} GROUP BY ENTRUST_ID) EEOH ON EEOH.ENTRUST_ID = RFPDT.TOTLE_TRADE_ID LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = RFPDT.TOTLE_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TMI.TRD_ID = TFPDT.TOTLE_TRADE_ID WHERE RFPDT.FINPROD_TYPE2 in ('F02', 'F03') AND ((RFPDT.TRADE_STATUS = '01' and (RFPDT.IS_CANCEL IS NULL OR RFPDT.IS_CANCEL = 'N')) OR RFPDT.IS_CANCEL = 'Y') and RFPDT.TRADE_DATE = to_date(#{platDate}, 'yyyy-MM-dd')
and RFPDT.TOTLE_TRADE_ID in
#{item}
and (EEOH.STATISTICAL_TIMES = 0 OR EEOH.STATISTICAL_TIMES IS null)
and RFPDT.QUOTE_TYPE in
#{item}
UNION ALL
SELECT '04' validStatus, RFPDT.QUOTE_TYPE quoteType, RFPDT.TRADE_AMT tradeAmt, RFPDT.RATE rate, RFPDT.REPO_TYPE repoType, RFPDT.REPO_TERM repoTerm, MCCI2.PARTY_ABBR ouPartyName, case when RFPDT.QUOTE_TYPE = '05' then SDL.ITEM_VALUE else MSCP.COUNTER_NAME end cpPartyName, MSCP.PARTY_ID partyId, NVL(SU.REAL_NAME,SUA.IBU_TRADER) ouTraderName, case when MCCT.TRADER_NAME is not null then MCCT.TRADER_NAME else RFPDT.COUNTER_TRADER end cpTraderName, RFPDT.SETTLE_SPEED settleSpeed/*清算速度*/, RFPDT.V_SETTLE_DATE vSettleDate, RFPDT.M_SETTLE_DATE mSettleDate, RFPDT.TRADE_DATE tradeDate, null dealDate, EEOH.STATISTICAL_TIMES statisticalTimes, RFPDT.TOTLE_TRADE_ID quoteId, NULL trdId, RFPDT.PS ps, RFPDT.CLEAR_TYPE settleType, RFPDT.DELIVERY_TYPE deliverytype, RFPDT.M_DELIVERY_TYPE mDeliveryType, RFPDT.CCY ccy, RFPDT.SETT_CCY settCcy, RFPDT.CREATE_USER createUser FROM WFL_REG_FIN_PRODUCT_DEAL_TOTAL RFPDT LEFT JOIN MST_COUNTER_PARTY MSCP ON MSCP.COUNTER_ID = RFPDT.COUNTER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI2 ON MCCI2.PARTY_ID = RFPDT.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = RFPDT.COUNTER_TRADER LEFT JOIN SYS_USER SU ON SU.USER_NAME = RFPDT.OU_TRADER_ID LEFT JOIN SYS_USER_ADD SUA ON SU.USER_ID = SUA.USER_ID LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'REGIST_ORG')SDL ON RFPDT.COUNTER_ID = SDL.ITEM_CODE LEFT JOIN (SELECT ENTRUST_ID, COUNT(1) STATISTICAL_TIMES FROM ETR_ENTRUST_OPER_HIS WHERE OPER_TYPE = #{OPR_TYPE_09} GROUP BY ENTRUST_ID) EEOH ON EEOH.ENTRUST_ID = RFPDT.TOTLE_TRADE_ID WHERE RFPDT.FINPROD_TYPE2 in ('F02', 'F03') AND ((RFPDT.TRADE_STATUS = '01' and (RFPDT.IS_CANCEL IS NULL OR RFPDT.IS_CANCEL = 'N')) OR RFPDT.IS_CANCEL = 'Y') and RFPDT.TRADE_DATE = to_date(#{platDate}, 'yyyy-MM-dd')
and RFPDT.TOTLE_TRADE_ID in
#{item}
and (EEOH.STATISTICAL_TIMES = 0 OR EEOH.STATISTICAL_TIMES IS null)
and RFPDT.QUOTE_TYPE in
#{item}

mapper.select:
select * from (
select
    TT.validStatus,
    TT.quoteType,
    TT.tradeAmt,
    TT.rate*100 rate,
    TT.repoTerm,
    TT.ouPartyName,
    TT.cpPartyName,
    TT.ouTraderName,
    TT.cpTraderName,
    TT.settleSpeed/*清算速度*/,
    TT.vSettleDate,
    TT.mSettleDate,
    TT.tradeDate,
    TT.dealDate,
    TT.statisticalTimes,
    TT.quoteId,
    TT.trdId,
    TT.ps,
    TT.settleType,
    TT.deliverytype,
    TT.mDeliveryType,
    TT.ccy,
    TT.settCcy,
    TT.createUser
 from (

) TT
LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'STATUS_VALID')D ON TT.validStatus = D.ITEM_CODE
LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'QUOTE_STYLE')F ON TT.quoteType = F.ITEM_CODE
LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ACCOUNT_SPEED')H ON TT.settleSpeed = H.ITEM_CODE
where
    1 = 1

        and TT.quoteId like '%' || #{quoteId} || '%'


        and TT.ps  = #{ps}/*交易方向*/


        /* 查询条件 交易方向*/
        AND TT.ps IN

            #{item}



        and TT.quoteType  = #{quoteType}/*报价方式*/


        and TT.settleSpeed  = #{settleSpeed}/*清算速度*/


        /* 查询条件 清算速度*/
        AND TT.settleSpeed IN

            #{item}



        and TT.repoTerm  = #{repoTerm}/*回购期限*/


        /* 查询条件 本方交易员*/
        AND TT.ouTraderName IN

            #{item}



        /* 查询条件 对手方*/
        AND TT.cpPartyName IN

            #{item}



        /* 查询条件 对手方交易员*/
        AND TT.cpTraderName IN

            #{item}



        and ( TT.createUser = #{loginUserId}
                or exists(
                            select 1 from SYS_USER_ROLE sur
                            left join SYS_ROLE sr on sur.ROLE_ID = sr.ROLE_ID
                            where sur.USER_ID = #{loginUserId} and sr.ROLE_POS = #{rolePos03}))


        and (
        D.ITEM_VALUE || F.ITEM_VALUE || H.ITEM_VALUE || TT.ouPartyName || TT.ouTraderName || TT.cpPartyName || TT.cpTraderName
            || TT.quoteId || TT.trdId like '%' || #{search} || '%'
        or to_char(TT.tradeAmt,'FM99990.9990')=#{search} or  TT.tradeAmt||'' =#{search}
        or to_char(TT.rate * 100,'FM99990.9990')=#{search} or  TT.rate||'' =#{search}
        or TT.repoTerm||'' =#{search}
        or to_char(TT.vSettleDate,'yyyy-MM-dd')=#{search}
        or to_char(TT.mSettleDate,'yyyy-MM-dd')=#{search}
        or to_char(TT.tradeDate,'yyyy-MM-dd')=#{search}
        or to_char(TT.dealDate,'yyyy-MM-dd')=#{search}
        or TT.statisticalTimes||'' =#{search}
        OR TT.settleSpeed LIKE '%' || decode(#{search}, 'T+0', '0', 'T+1', '1', 'T+2', '2', #{search}) || '%'
        )

)

    order by ${sort} ${direction}

